import json,glob,re,hashlib
found=set()
for f in glob.glob("/var/openhands/conversations/8b55afd6*/events/*.json"):
    try: s=open(f).read()
    except: continue
    for m in re.finditer(r'(sk-obs1_[A-Za-z0-9_-]{20,})',s):
        found.add(m.group(1))
print("key ditemukan:",len(found))
acc={}
for n,l in enumerate(open("ob_accounts.txt"),1):
    p=[x.strip() for x in l.split("|")]
    if len(p)>=3 and p[1].startswith("sk-obs1"):
        acc[hashlib.sha256(p[1].encode()).hexdigest()[:8]]=(n,p[0],p[2])
pro={}
for l in open("ob_results.jsonl"):
    try: d=json.loads(l)
    except: continue
    nn=str(d.get("account_number") or "")
    if nn and nn!="None": pro[nn]=(str(d.get("pro_access_until"))[:10] if d.get("pro_access_until") else "", str(d.get("created_at"))[:10] if d.get("created_at") else "")
for k in found:
    fp=hashlib.sha256(k.encode()).hexdigest()[:8]
    hit=acc.get(fp)
    print(f"\nkey: {k[:20]}...{k[-6:]} (len {len(k)})")
    print(f"fingerprint: {fp}")
    if hit: print(f"  -> akun baris {hit[0]}, NOMOR AKUN {hit[1]}, saldo {hit[2]} | pro {pro.get(hit[1],('-','-'))}")
    else: print("  -> tidak ada di ob_accounts.txt")
